\title{Primitive Prime Divisors of Fibonacci Numbers:\\
A Verified Account of the Prime-Index Case\\
and a Computational Frontier for the Composite Case}
\author{Aristotle}
\date{June 24, 2026}

\begin{document}

\begin{abstract}
A primitive prime divisor of the $n^{\text{th}}$ Fibonacci number $F(n)$ is a
prime $p$ dividing $F(n)$ but dividing no earlier Fibonacci number $F(k)$ with
$0 < k < n$. Carmichael's theorem (1913) asserts that $F(n)$ has a primitive
prime divisor for every $n$ outside a small exceptional set. We give a complete,
elementary, and fully machine-checked proof of the \emph{prime-index case}: if
$n$ is prime and $n \ge 13$ (indeed $n \ge 3$ suffices), then $F(n)$ has a
primitive prime divisor. The proof rests on the strong divisibility identity
$\gcd(F(m), F(n)) = F(\gcd(m,n))$ together with the observation that the
primality of the index collapses any nontrivial common index to $1$. We then
develop the composite-index case via an explicit \emph{primitive-part}
construction and prove that whenever the primitive part exceeds $1$, its least
prime factor is a primitive prime divisor. A verified finite computation
establishes the survival inequality (primitive part $> 1$) for every composite
index in $13 \le n \le 10000$. The unbounded tail $n > 10000$ is identified as
the remaining open problem.
\end{abstract}

\maketitle

\section{Introduction}

The Fibonacci sequence $F : \N \to \N$ is defined by $F(0) = 0$, $F(1) = 1$, and
$F(n+2) = F(n+1) + F(n)$. Its arithmetic is unusually rigid: the sequence is a
\emph{strong divisibility sequence}, meaning
\begin{equation}\label{eq:sds}
\gcd\bigl(F(m), F(n)\bigr) = F\bigl(\gcd(m,n)\bigr) \qquad (m, n \ge 0).
\end{equation}
This single identity organizes essentially everything about Fibonacci
divisibility, including the location of first appearances of prime factors.

\begin{definition}[Primitive prime divisor]
A prime $p$ is a \emph{primitive prime divisor} of $F(n)$ if $p \mid F(n)$ and,
for every $k$ with $0 < k < n$, we have $p \nmid F(k)$.
\end{definition}

Carmichael's theorem states that $F(n)$ has a primitive prime divisor for all
$n \notin \{1, 2, 6, 12\}$ (with $F(1)=F(2)=1$). The exceptions are genuine:
$F(1)=F(2)=1$ have no prime factors, $F(6) = 8 = 2^3$ repeats the prime $2$ of
$F(3)=2$, and $F(12) = 144 = 2^4 \cdot 3^2$ repeats earlier primes.

This paper makes two contributions. First, a complete, elementary, machine-checked
proof of the prime-index case (Theorem~\ref{thm:prime}). Second, an algorithmic
and computational treatment of the composite-index case
(Sections~\ref{sec:primpart}--\ref{sec:comp}): we construct the primitive part of
$F(n)$ as an explicit procedure, prove its correctness, and verify by exact
computation that the primitive part exceeds $1$ for every composite $n$ in
$[13, 10000]$. We are scrupulous about status: the prime case is unconditionally
proved; the composite case is established for $13 \le n \le 10000$; the infinite
tail is an explicitly flagged open problem (Section~\ref{sec:future}).

\section{Preliminaries}

We work over $\N$ and use three standard facts.
\begin{itemize}
\item \textbf{(P1) Existence of a prime divisor.} Every $m \ne 1$ has a prime
  divisor.
\item \textbf{(P2) Strong divisibility identity~\eqref{eq:sds}.} An immediate
  corollary is the \emph{divisibility form}: if $p \mid F(m)$ and $p \mid F(n)$,
  then $p \mid F(\gcd(m,n))$, since $p \mid \gcd(F(m),F(n)) = F(\gcd(m,n))$.
\item \textbf{(P3) Coprimality below a prime.} If $0 < k < n$ then $n \nmid k$;
  and if $n$ is prime, $\gcd(n,k) \in \{1, n\}$, so $\gcd(n,k) = 1$.
\end{itemize}
We also use $F(n) > 1$ for $n \ge 3$ and $F(n) \ge \varphi^{\,n-2}$ for $n \ge 1$,
where $\varphi = (1+\sqrt5)/2$.

\section{The Prime-Index Case}

\begin{theorem}[Carmichael, prime case]\label{thm:prime}
Let $n$ be prime with $n \ge 13$. Then $F(n)$ has a primitive prime divisor:
there exists a prime $p$ with $p \mid F(n)$ and $p \nmid F(k)$ for every $k$ with
$0 < k < n$.
\end{theorem}

The hypothesis $n \ge 13$ is convenient for downstream uniformity but is stronger
than necessary; the proof works verbatim for any prime $n \ge 3$.

\begin{proof}
Since $n \ge 13 \ge 3$, we have $F(n) > 1$, so by (P1) there is a prime $p$ with
$p \mid F(n)$. We claim every such $p$ is primitive. Fix $k$ with $0 < k < n$ and
suppose for contradiction that $p \mid F(k)$. Then $p \mid F(n)$ and $p \mid
F(k)$, so by the divisibility form of (P2), $p \mid F(\gcd(n,k))$. By (P3), since
$n$ is prime and $0 < k < n$, we have $\gcd(n,k) = 1$. Hence $p \mid F(1) = 1$,
contradicting that $p$ is prime. Therefore $p \nmid F(k)$ for all $0 < k < n$.
\end{proof}

\begin{remark}
The role of primality is razor-sharp: it is used only to force $\gcd(n,k) = 1$.
This is why the argument transfers to any strong divisibility sequence with
$F(1)$ a unit.
\end{remark}

\begin{lemma}[Divisor-to-all bridge]\label{lem:bridge}
Let $n > 0$ and let $p$ be a prime with $p \mid F(n)$. Suppose $p \nmid F(d)$ for
every divisor $d$ of $n$ with $0 < d < n$. Then $p \nmid F(k)$ for every $k$ with
$0 < k < n$.
\end{lemma}

\begin{proof}
Suppose $0 < k < n$ and $p \mid F(k)$. With $p \mid F(n)$, the divisibility form
of (P2) gives $p \mid F(\gcd(n,k))$. Set $d = \gcd(n,k)$; then $d \mid n$, $d >
0$, and $d \le k < n$, so $d$ is a proper divisor of $n$ with $p \mid F(d)$, a
contradiction.
\end{proof}

For a prime $n$ the only proper divisor is $1$, and $F(1) = 1$ is divisible by no
prime, so Lemma~\ref{lem:bridge} instantly recovers Theorem~\ref{thm:prime}.

\section{The Composite-Index Case: the Primitive-Part Construction}
\label{sec:primpart}

\begin{definition}[Proper divisors]
For $n \in \N$, $\propDivs(n) = \{\, d : 0 < d < n,\ d \mid n \,\}$, realized as a
finite list.
\end{definition}

\begin{definition}[Factor-stripping routine]
Given $r, m$ and a fuel budget, $\stripAllAux$ repeatedly replaces $r$ by
$r/\gcd(r,m)$ until $\gcd(r,m) = 1$ (or the fuel runs out, or $m \le 1$). Each
step removes one layer of the primes common to $r$ and $m$.
\end{definition}

\begin{definition}[Primitive part]
The \emph{primitive part} $\primPart(n)$ of $F(n)$ starts from $F(n)$ and, for
each $d \in \propDivs(n)$, strips all factors shared with $F(d)$. Concretely,
$\primPart(n)$ folds $\stripAllAux$ over $\propDivs(n)$, beginning at $F(n)$.
\end{definition}

\begin{lemma}[Stripping divides]
$\stripAllAux(r,m,\mathrm{fuel}) \mid r$.
\end{lemma}

\begin{lemma}[Stripping achieves coprimality]
With $\mathrm{fuel} \ge r$, $m > 1$, $r > 0$, one has
$\gcd(\stripAllAux(r,m,\mathrm{fuel}), m) = 1$. Each step with $\gcd > 1$ strictly
decreases $r$, so $r$ steps suffice.
\end{lemma}

\begin{lemma}[Primitive part divides]\label{lem:ppdvd}
$\primPart(n) \mid F(n)$.
\end{lemma}

\begin{lemma}[Coprime to proper divisors]\label{lem:ppcop}
If $\primPart(n) > 1$, its least prime factor divides no $F(d)$ for $d \in
\propDivs(n)$.
\end{lemma}

\begin{lemma}[Primitive part certifies a primitive divisor]\label{lem:ppimp}
Let $n \ge 3$ and suppose $\primPart(n) > 1$. Then the least prime factor of
$\primPart(n)$ is a primitive prime divisor of $F(n)$.
\end{lemma}

\begin{proof}
Let $p$ be the least prime factor of $\primPart(n)$. By Lemma~\ref{lem:ppdvd},
$p \mid \primPart(n) \mid F(n)$. Take any $0 < k < n$ with $p \mid F(k)$. With
$p \mid F(n)$, (P2) gives $p \mid F(\gcd(k,n))$. But $\gcd(k,n)$ is a proper
divisor of $n$, so by Lemma~\ref{lem:ppcop}, $p \nmid F(\gcd(k,n))$, a
contradiction.
\end{proof}

Lemma~\ref{lem:ppimp} reduces Carmichael's composite case to a single inequality
for each $n$: $\primPart(n) > 1$.

\section{Verified Computation over a Finite Range}\label{sec:comp}

\begin{proposition}[Verified survival sweep]\label{prop:check}
For every $n$ with $13 \le n \le 10000$, either $n$ is prime or
$\primPart(n) > 1$.
\end{proposition}

The statement is a finite conjunction of decidable facts, discharged by direct
evaluation of $\primPart(n)$ and a primality test. No exceptions occur.

\begin{theorem}[Composite case on the verified range]\label{thm:comp}
For composite $n$ with $13 \le n \le 10000$, $F(n)$ has a primitive prime divisor.
\end{theorem}

\begin{proof}
By Proposition~\ref{prop:check}, $n$ composite forces $\primPart(n) > 1$; apply
Lemma~\ref{lem:ppimp}.
\end{proof}

Combining Theorem~\ref{thm:prime} (all prime indices) with
Theorem~\ref{thm:comp} (composite indices in range) gives Carmichael's conclusion
for every $13 \le n \le 10000$, and Theorem~\ref{thm:prime} alone gives it for all
prime indices without upper bound.

\paragraph{Status of the tail.} For composite $n > 10000$ the computation is
replaced by the growth principle: $F(n)$ grows like $\varphi^n$, while the product
of the $F(d)$ over proper divisors grows much more slowly. Turning this into a
verified bound is the remaining work; the tail is currently an explicit open case.

